// Builds and scales a packed local matrix from g_BattleLimitLandscaperScaleFactor2 and
// g_BattleLimitLandscaperBaseDistance, sets translation from
// g_BattleLimitLandscaperFragmentRecords.centerXSaved/.centerZSaved and the second short of arg1, then
// installs it. When scene and its first pointer are nonzero, independently acquires two offscreen
// requests for stage part one, copying the matrix as transposed float form and four signed viewport
// shorts from arg2. Both set pageFillEnabled, pageFillStepX and pageFillStepY to one and renderKind
// to four; blendMode is four in the first and one in the second. Saves each successful request's
// slotIndex into g_BattleLimitLandscaperOffscreenSlot and g_BattleLimitLandscaperScaleFactor1 respectively. Failed acquisitions leave their global slot
// unchanged and do not prevent the second attempt. The matrix is installed before the scene pointer
// is checked.
// FUNCTION: FF7 0x00494b35
void __cdecl BattleFx_LimitLandscaperQueueStageOffscreenRequests(short *modelPointers, BattleFxScreenRect *viewport)
{
#pragma pack(push, 1)
    /* Locals by stack slot: see FRAME UNION in lib/codegen.h. */
    union {
        unsigned char storage[52];
        int stageId;
        struct { unsigned char pad_to_4[0x4]; GfxOffscreenRequest *request; };
        struct { unsigned char pad_to_8[0x8]; PsxMatrix gaiseiMatrix; };
    } frame;
#pragma pack(pop)

    RotMatrixXYZ(g_BattleLimitLandscaperScaleFactor2, &frame.gaiseiMatrix);
    ScaleMatrix(&frame.gaiseiMatrix, &g_BattleLimitLandscaperBaseDistance);
    frame.gaiseiMatrix.t[0] = g_BattleLimitLandscaperFragmentRecords.centerXSaved;
    frame.gaiseiMatrix.t[1] = g_BattleLimitLandscaperFragmentRecords.centerZSaved;
    frame.gaiseiMatrix.t[2] = modelPointers[1];
    SetRotMatrix(&frame.gaiseiMatrix);
    SetTransMatrix(&frame.gaiseiMatrix);
    if (g_pBattle3dScene != 0 && g_pBattle3dScene->stageId != 0) {
        frame.stageId = g_pBattle3dScene->stageId;
        frame.request = (GfxOffscreenRequest *)Battle3d_AcquireOffscreenRequest();
        if (frame.request != 0) {
            frame.request->kind = 1;
            frame.request->mesh = (int)BattleStage_GetPartMesh(1, (Battle3dStageRecord *)frame.stageId);
            GtePsxMatrixToFloat4x4Transposed(&frame.gaiseiMatrix, (char *)frame.request + 0x88);
            frame.request->pageFillEnabled = 1;
            frame.request->renderKind = 4;
            frame.request->blendMode = BLEND_NONE;
            frame.request->viewportX = viewport->x;
            frame.request->viewportY = viewport->y;
            frame.request->viewportW = viewport->width;
            frame.request->viewportH = viewport->height;
            frame.request->pageFillStepX = 1;
            frame.request->pageFillStepY = 1;
            g_BattleLimitLandscaperOffscreenSlot = frame.request->slotIndex;
        }
        frame.request = (GfxOffscreenRequest *)Battle3d_AcquireOffscreenRequest();
        if (frame.request != 0) {
            frame.request->kind = 1;
            frame.request->mesh = (int)BattleStage_GetPartMesh(1, (Battle3dStageRecord *)frame.stageId);
            GtePsxMatrixToFloat4x4Transposed(&frame.gaiseiMatrix, (char *)frame.request + 0x88);
            frame.request->pageFillEnabled = 1;
            frame.request->renderKind = 4;
            frame.request->blendMode = BLEND_ADDITIVE;
            frame.request->viewportX = viewport->x;
            frame.request->viewportY = viewport->y;
            frame.request->viewportW = viewport->width;
            frame.request->viewportH = viewport->height;
            frame.request->pageFillStepX = 1;
            frame.request->pageFillStepY = 1;
            g_BattleLimitLandscaperScaleFactor1[0] = frame.request->slotIndex;
        }
    }
}

// Returns while paused, advances task XYZ by saved velocity and emits two
// BattleFx_LimitLandscaperAnimatedSpriteTask records at the new position with velY zero and
// variants zero/one. Emits one BattleFx_LimitLandscaperBouncingSpriteTask at new X/Z with Y zero,
// random low-twelve-bit angle giving X/Z velocity of cosine/sine times hundred shifted twelve, Y
// velocity expressed as negative rand remainder modulo 200 minus hundred and variant zero through
// two. Advances count and retires on exactly ten.
// FUNCTION: FF7 0x00494d62
void __cdecl BattleFx_LimitLandscaperTravelingSpriteEmitterTask(void)
{
    BattleFxLandscaperEmitter *taskPtr;
    short angle;
    short i;
    BattleFxLimitLandscaperSprite *pSprite;

    taskPtr = (BattleFxLandscaperEmitter *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    taskPtr->posX += taskPtr->velX;
    taskPtr->posY += taskPtr->velY;
    taskPtr->posZ += taskPtr->velZ;
    for (i = 0; i < 2; i++) {
        pSprite = (BattleFxLimitLandscaperSprite *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitLandscaperAnimatedSpriteTask);
        pSprite->posX = taskPtr->posX;
        pSprite->posY = taskPtr->posY;
        pSprite->posZ = taskPtr->posZ;
        pSprite->velY = 0;
        pSprite->spriteKind = i;
    }
    pSprite = (BattleFxLimitLandscaperSprite *)BATTLE_NEW_TASK_SLOT(BattleFx_LimitLandscaperBouncingSpriteTask);
    pSprite->posX = taskPtr->posX;
    pSprite->posZ = taskPtr->posZ;
    pSprite->posY = 0;
    angle = rand() % 0x1000;
    pSprite->velX = CosFixed(angle) * 0x64 >> 12;
    pSprite->velZ = SinFixed(angle) * 0x64 >> 12;
    pSprite->velY = -rand() % 200 - 100;
    pSprite->spriteKind = rand() % 3;
    (taskPtr->step)++;
    if (taskPtr->step == 10) {
        taskPtr->ownerSlot = BATTLE_TASK_FREE;
    }
}

