                textureQuadPacket->texCoord0 = record->primWord;
                textureQuadPacket->uvWord1 = record->clut;
                textureQuadPacket->uvWord2 = record->texPage;
                textureQuadPacket->texCoord3 = record->vertex0Offset;
                textureQuadPacket->flags = flagsWord;
