                    textureQuadPacket->u0 >>= 1;
                    textureQuadPacket->v0 >>= 1;
                    textureQuadPacket->u1 >>= 1;
                    textureQuadPacket->v1 >>= 1;
                    textureQuadPacket->u2 >>= 1;
                    textureQuadPacket->v2 >>= 1;
                    textureQuadPacket->u3 >>= 1;
                    textureQuadPacket->v3 >>= 1;
