// Per-frame handler for the current battle-effect slot; returns at once while the pause flag
// g_BattleIsPaused is set. Adds the slot's fallSpeed to g_BattleActorRecords[actor].posY, where the
// actor is the slot's actorIndex, then grows the speed by 0xA each frame. When posY
// reaches the per-actor limit g_BattleLimitLandscaperTargetSavePositions[actor].posY it clamps to the limit, and if bit actor
// of g_BattleLimitLandscaperTargets is set calls Battle_PostActorHitOrHurtMessage(actor) and
// Battle_PlaySfxPannedToActor(0x149, actor, 0x40), then retires the slot.
// FUNCTION: FF7 0x0049680c
void __cdecl BattleFx_LimitLandscaperActorFallTask(void)
{
    BattleFxLandscaperFallSlot *task;

    task = (BattleFxLandscaperFallSlot *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    g_BattleActorRecords[task->actorIndex].posY += task->fallSpeed;
    task->fallSpeed += 10;
    if (g_BattleLimitLandscaperTargetSavePositions[task->actorIndex].posY <= g_BattleActorRecords[task->actorIndex].posY) {
        g_BattleActorRecords[task->actorIndex].posY = g_BattleLimitLandscaperTargetSavePositions[task->actorIndex].posY;
        if ((g_BattleLimitLandscaperTargets & 1 << task->actorIndex) != 0) {
            Battle_PostActorHitOrHurtMessage(task->actorIndex);
            Battle_PlaySfxPannedToActor(0x149, (short)task->actorIndex, 0x40);
        }
        task->ownerSlot = BATTLE_TASK_FREE;
    }
}

// For 112 entries adds velocity triples to g_BattleLimitLandscaperActorFallData position triples, adds 20 to each Y
// velocity, and when Y position becomes positive clamps it to zero and negates Y velocity.
// FUNCTION: FF7 0x0049690c
void __cdecl BattleFx_LimitLandscaperUpdateFragmentPositions(void)
{
    short i;

    for (i = 0; i < 112; i++) {
        g_BattleLimitLandscaperActorFallData[i].fallPosition += g_BattleLimitLandscaperFragmentRecords.velocities[i].fallVelocity;
        g_BattleLimitLandscaperActorFallData[i].posY += g_BattleLimitLandscaperFragmentRecords.velocities[i].velocityY;
        g_BattleLimitLandscaperActorFallData[i].posX += g_BattleLimitLandscaperFragmentRecords.velocities[i].velocityX;
        g_BattleLimitLandscaperFragmentRecords.velocities[i].velocityY += 20;
        if (g_BattleLimitLandscaperActorFallData[i].posY > 0) {
            g_BattleLimitLandscaperActorFallData[i].posY = 0;
            g_BattleLimitLandscaperFragmentRecords.velocities[i].velocityY = -g_BattleLimitLandscaperFragmentRecords.velocities[i].velocityY;
        }
    }
}

// Draws a white flash only while g_BattleLimitLandscaperFlashLevel is positive, before checking pause.
// When unpaused subtracts 0x40 from a positive level without clamping, alternately adds 32 or -32 to
// g_BattleCameraFocalPoint.focalPointY using counter parity, advances the counter and retires exactly at forty.
// FUNCTION: FF7 0x004969fa
void __cdecl BattleFx_LimitLandscaperFlashShakeTask(void)
{
    int p; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    BattleFxLandscaperShakeSlot *q;

    q = (BattleFxLandscaperShakeSlot *)BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleLimitLandscaperFlashLevel > 0) {
        g_BattleOverlayDrawListHead = BattleFx_FlashScreenWhite(*(char *)&g_BattleLimitLandscaperFlashLevel, *(char *)&g_BattleLimitLandscaperFlashLevel, *(char *)&g_BattleLimitLandscaperFlashLevel);
    }
    if (g_BattleIsPaused != 0) {
        return;
    }
    if (g_BattleLimitLandscaperFlashLevel > 0) {
        g_BattleLimitLandscaperFlashLevel -= 0x40;
    }
    g_BattleCameraFocalPoint.focalPointY += (short)(32 - (q->step % 2 << 6));
    (q->step)++;
    if (q->step == 40) {
        q->ownerSlot = BATTLE_TASK_FREE;
    }
}

// When unpaused adds an alternating counter-dependent displacement to the camera word
// g_BattleCameraFocalPoint.focalPointY, advances the current-slot counter, and retires it exactly
// at 6.
// FUNCTION: FF7 0x00496ac1
void __cdecl BattleFx_LimitLandscaperCameraShakeTask(void)
{
    BattleTaskSlot *task;

    task = BATTLE_CURRENT_TASK_SLOT;
    if (g_BattleIsPaused != 0) {
        return;
    }
    g_BattleCameraFocalPoint.focalPointY += (short)((6 - task->frameCounter) * 10 * (1 - (task->frameCounter % 2 << 1)));
    (task->frameCounter)++;
    if (task->frameCounter == 6) {
        task->ownerSlot = BATTLE_TASK_FREE;
    }
}
